131		}
132		c2, _ := s.Commitment("c2")
133		if c2.Quantity != 4 || c2.Used != 0 || c2.Unused() != 4 || c2.Canceled || c2.Expired {
134			t.Fatalf("c2 mutated by rejected use: %+v", c2)
135		}
136		assertExceededBaseline(t, s)
137	
138		// 2) 沿用刚才失败的同一编号、仍指向 c1，改为合法数量 3 件：成功。返回
139		//    的使用记录必须明确对应这个编号、这笔承诺和三件数量，不能被先前的
140		//    失败误判为编号冲突。
141		first, err := s.Use("uRetry", "c1", 3, nowOK)
142		if err != nil {
143			t.Fatalf("same id with legal quantity 3 after rejection: %v", err)
144		}
145		if first != (Usage{ID: "uRetry", CommitmentID: "c1", Quantity: 3}) {
146			t.Fatalf("successful usage = %+v, want {uRetry c1 3}", first)
147		}
148	
149		// c1 累计已用 5、未用 0（恰好用完余量）；c2 保持原定 4、已用 0、未用 4。
150		c1b, _ := s.Commitment("c1")
151		if c1b.Quantity != 5 || c1b.Used != 5 || c1b.Unused() != 0 {
152			t.Fatalf("c1 after 3-piece use: %+v, want qty=5 used=5 unused=0", c1b)
153		}
154		c2b, _ := s.Commitment("c2")
155		if c2b.Quantity != 4 || c2b.Used != 0 || c2b.Unused() != 4 {
156			t.Fatalf("c2 disturbed by c1 use: %+v, want qty=4 used=0 unused=4", c2b)
157		}
158		// 实物 10-3=7，有效占用 4（c1 未用 0 + c2 未用 4），可承诺 3。
159		assertPartAccount(t, s, 7, 4, 3)
160	
161		// 按备件查看：c1 显示 5/5/0 且仍归属 r1，c2 显示 4/0/4 且仍归属 r2。
162		st, err := s.PartStatus("part1", nowOK)
163		if err != nil {
164			t.Fatalf("part status after success: %v", err)
165		}
166		sd1 := mustDetailByID(t, st.Details, "c1")
167		if sd1.Status != CommitmentActive || sd1.RequestID != "r1" ||
168			sd1.OriginalQuantity != 5 || sd1.UsedQuantity != 5 || sd1.RemainingQuantity != 0 {
169			t.Fatalf("c1 detail after success: %+v, want active r1 qty=5 used=5 remaining=0", sd1)
170		}
171		sd2 := mustDetailByID(t, st.Details, "c2")
172		if sd2.Status != CommitmentActive || sd2.RequestID != "r2" ||
173			sd2.OriginalQuantity != 4 || sd2.UsedQuantity != 0 || sd2.RemainingQuantity != 4 {
174			t.Fatalf("c2 detail after success: %+v, want active r2 qty=4 used=0 remaining=4", sd2)
175		}
176		// 按请求查看：r1 看到自己用完的 c1，r2 只看到原值不变的 c2。
177		v1, err := s.RequestView("r1", nowOK)
178		if err != nil {
179			t.Fatalf("request view r1: %v", err)
180		}
181		if rv := mustDetailByID(t, v1.Commitments, "c1"); rv.UsedQuantity != 5 || rv.RemainingQuantity != 0 {
182			t.Fatalf("r1 view after success: %+v, want used=5 remaining=0", rv)
183		}
184		v2, err := s.RequestView("r2", nowOK)
185		if err != nil {
186			t.Fatalf("request view r2: %v", err)
187		}
188		if rv := mustDetailByID(t, v2.Commitments, "c2"); rv.UsedQuantity != 0 || rv.RemainingQuantity != 4 {
189			t.Fatalf("r2 view after success: %+v, want used=0 remaining=4", rv)
190		}
191	
192		// 3) 成功后原样提交：取回这次三件的使用记录，数量与库存不再变化。
193		again, err := s.Use("uRetry", "c1", 3, nowOK)
194		if err != nil || again != first {
195			t.Fatalf("identical resubmit = %+v, err %v; want first result %+v", again, err, first)
196		}
197		if c := mustCommitment(t, s, "c1"); c.Used != 5 {
198			t.Fatalf("identical resubmit deducted again: c1 = %+v", c)
199		}
200		assertPartAccount(t, s, 7, 4, 3)
201	
202		// 4) 沿用该编号改回先前被业务拒绝的 4 件：编号内容已由首次成功确定，
203		//    此时返回 ErrConflict，三件的成功结果与全部数量保留。
204		if conflicted, err := s.Use("uRetry", "c1", 4, nowOK); !errors.Is(err, ErrConflict) || conflicted != (Usage{}) {
205			t.Fatalf("change back to rejected 4: usage=%+v err=%v, want ErrConflict with empty result", conflicted, err)
206		}
207		if c := mustCommitment(t, s, "c1"); c.Used != 5 || c.Unused() != 0 {
208			t.Fatalf("c1 changed by conflict: %+v, want used=5 unused=0", c)
209		}
210		if c := mustCommitment(t, s, "c2"); c.Used != 0 || c.Unused() != 4 {
211			t.Fatalf("c2 changed by conflict: %+v, want used=0 unused=4", c)
212		}
213		assertPartAccount(t, s, 7, 4, 3)
214		// 三件的成功记录仍可原样取回。
215		if got, err := s.Use("uRetry", "c1", 3, nowOK); err != nil || got != first {
216			t.Fatalf("three-piece result lost after conflict: got %+v err %v, want %+v", got, err, first)
217		}
218	}
219	
220	// TestUsageExceededRejectionLeavesIDFreeForOtherCommitment 补充锁定“业务拒绝
221	// 不提前占住编号”：同一新编号在 c1 上申请 4 件被 ErrUsageExceeded 拒绝后，
222	// 编号没有绑定到 c1，也没有记录被拒绝的内容；把它指向未用数量充足的 c2
223	// 申请 4 件仍是一笔合法的新使用并成功。此后编号内容由这次成功确定，再指向
224	// c1 提交即按 ErrConflict 处理，c1 的数量自始至终不被波及。
225	func TestUsageExceededRejectionLeavesIDFreeForOtherCommitment(t *testing.T) {
226		s := exceededRetryStore(t)
227	
228		if _, err := s.Use("uRejected", "c1", 4, nowOK); !errors.Is(err, ErrUsageExceeded) {
229			t.Fatalf("use 4 on c1 (unused 3): got %v, want ErrUsageExceeded", err)
230		}
231	
232		// 同一编号改指 c2、数量 4（c2 未用恰为 4）：业务拒绝没有占用编号，
233		// 这仍是全新的合法使用，应当成功并把编号内容绑定为 {uRejected c2 4}。
234		u, err := s.Use("uRejected", "c2", 4, nowOK)
235		if err != nil {
236			t.Fatalf("rejected id reused against c2 with legal quantity: %v", err)
237		}
238		if u != (Usage{ID: "uRejected", CommitmentID: "c2", Quantity: 4}) {
239			t.Fatalf("usage = %+v, want {uRejected c2 4}", u)
240		}
241	
242		// c2 被用完 4 件；c1 维持 5/2/3，拒绝与 c2 的使用都没有动它。
243		if c := mustCommitment(t, s, "c1"); c.Quantity != 5 || c.Used != 2 || c.Unused() != 3 {
244			t.Fatalf("c1 disturbed: %+v, want qty=5 used=2 unused=3", c)
245		}
246		if c := mustCommitment(t, s, "c2"); c.Quantity != 4 || c.Used != 4 || c.Unused() != 0 {
247			t.Fatalf("c2 after use: %+v, want qty=4 used=4 unused=0", c)
248		}
249		// 实物 10-4=6，有效占用 3（只剩 c1 未用 3），可承诺 3。
250		assertPartAccount(t, s, 6, 3, 3)
251	
252		// 编号内容已绑定到 c2 的 4 件：再指向 c1 即使数量合法（3 件）也冲突，
253		// 且原样取回的仍是 c2 的四件记录。
254		if _, err := s.Use("uRejected", "c1", 3, nowOK); !errors.Is(err, ErrConflict) {
255			t.Fatalf("rebound id pointed at c1: got %v, want ErrConflict", err)
256		}
257		if got, err := s.Use("uRejected", "c2", 4, nowOK); err != nil || got != u {
258			t.Fatalf("record after conflict: got %+v err %v, want %+v", got, err, u)
259		}
260		assertPartAccount(t, s, 6, 3, 3)
261	}
262	
263	// mustCommitment 取回承诺副本，不存在时直接失败。
264	func mustCommitment(t *testing.T, s *Store, id string) Commitment {
265		t.Helper()
266		c, err := s.Commitment(id)
267		if err != nil {
268			t.Fatalf("commitment %s: %v", id, err)
269		}
270		return c
271	}
