368	func TestUseAfterCancelOrExpireRetriesOriginal(t *testing.T) {
369		s := newStore(t)
370		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
371			t.Fatalf("reserve: %v", err)
372		}
373		if _, err := s.Use("u1", "c1", 2, nowOK); err != nil {
374			t.Fatalf("use: %v", err)
375		}
376		// 取消后重试同一使用：仍返回原结果，不再次扣减。
377		if _, err := s.Cancel("c1", nowOK); err != nil {
378			t.Fatalf("cancel: %v", err)
379		}
380		u, err := s.Use("u1", "c1", 2, nowOK)
381		if err != nil || u.Quantity != 2 {
382			t.Fatalf("use after cancel: %+v err %v", u, err)
383		}
384		c, _ := s.Commitment("c1")
385		if c.Used != 2 {
386			t.Fatalf("retry after cancel double-deducted: used=%d", c.Used)
387		}
388	
389		// 到期后重试同一使用：仍返回原结果。
390		s2 := newStore(t)
391		if _, err := s2.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
392			t.Fatalf("reserve: %v", err)
393		}
394		if _, err := s2.Use("u1", "c1", 2, nowOK); err != nil {
395			t.Fatalf("use: %v", err)
